Definition cnt_row_exit (sp gp tp t0 t1 t2 s0 s1 a5 a6 a7 s2 s4 s5 s6 s10 t3 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
    (B : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' a0' a1' a2' a3' s3' s7' s9' t4' : word) (S' : Z),
    ms' = MS (mkR ra' sp gp tp t0 t1 t2 s0 s1 a0' a1' a2' a3' (Z_to_bv 64 S') a5 a6 a7
                  s2 s3' s4 s5 s6 s7' (Z_to_bv 64 1) s9' s10 (Z_to_bv 64 SHB) t3 t4' t5 t6)
             F (Z_to_bv 64 0x12dd08) fc None m (seg_rom asegs)
    /\ 0 <= S' <= B.

Lemma cnt_row : forall
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 t3 t4 t5 t6 : word) F fc (m : mem)
    (data n line fw eb wpl fp S B tab : Z) (em : word) (bs : list byte) (ws : list word),
  t3 = Z_to_bv 64 fw -> t5 = Z_to_bv 64 fw -> t2 = Z_to_bv 64 eb -> t0 = Z_to_bv 64 line -> s6 = Z_to_bv 64 line ->
  a4 = Z_to_bv 64 S -> s5 = Z_to_bv 64 tab -> a7 = Z_to_bv 64 (18446744073709551615 - tab) -> t1 = Z_to_bv 64 0 -> s1 = Z_to_bv 64 fp ->
  rw_cells asegs m (fp + 48) [C8 em; C8 (Z_to_bv 64 1)] -> 0 < fp -> fp + 64 <= 2^47 ->
  0 <= fw <= wpl -> (eb <> 0 -> fw < wpl) -> 0 <= eb < 32 -> wpl <= 2^20 -> 0 <= S -> S + 32 * wpl <= B -> B < 2^31 ->
  data <= line -> line mod 4 = 0 -> line + 4 * wpl <= data + n -> 0 < data -> data mod 8 = 0 -> data + n <= 2^47 ->
  (data + n <= 0x7fff7000 \/ 0x10007fff8000 <= data) ->
  bytes_at asegs m data bs -> Z.of_nat (length bs) = n -> acc asegs m data n ->
  0 < tab -> tab mod 16 = 0 -> tab + 1024 <= 2^47 -> (tab + 1024 <= 0x7fff7000 \/ 0x10007fff8000 <= tab) ->
  u32arr asegs m tab ws -> Z.of_nat (length ws) = 256 -> tab_ok ws 256 -> acc asegs m tab 1024 ->
  mem_inv asegs m ->
  evt asegs (cnt_row_exit sp gp tp t0 t1 t2 s0 s1 a5 a6 a7 s2 s4 s5 s6 s10 t3 t5 t6 F fc m B)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 (Z_to_bv 64 SHB) t3 t4 t5 t6)
